import unicodedata

def slugify(s):
    s = s.lower()
    s = unicodedata.normalize('NFKD', s)
    s = s.encode('ascii', 'ignore').decode('ascii')
    out = []
    prev_dash = False
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_dash = False
        else:
            if out and not prev_dash:
                out.append('-')
                prev_dash = True
    return ''.join(out).strip('-')

