import unicodedata

def slugify(s):
    s = unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii').lower()
    parts = [p for p in re.split(r'[^a-z0-9]+', s) if p]
    return '-'.join(parts)

import unicodedata

def slugify(s):
    s = unicodedata.normalize('NFKD', s.lower()).encode('ascii', 'ignore').decode()
    out = []
    prev_sep = True
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_sep = False
        elif not prev_sep:
            out.append('-')
            prev_sep = True
    if out and out[-1] == '-':
        out.pop()
    return ''.join(out)

