def slug_unique(names):
    seen = {}
    result = []
    for name in names:
        base = slugify(name)
        count = seen.get(base, 0)
        seen[base] = count + 1
        if count == 0:
            result.append(base)
        else:
            result.append(f'{base}-{count + 1}')
    return result
